import '../tokens/tokens.css'; // the colour tokens this icon uses, so it never depends on the page importing them
import styles from './FileTypeIcon.module.css';
import { FILE_PDF_BOX } from './file-pdf-box';

export interface FileTypeIconProps {
  kind: 'pdf';
  /** The box in px. The tile fills 3/4 of it, as in Drive's 18 px tile inside a 24 px box. */
  size?: 18 | 24;
}

/**
 * The PDF file-type icon: Drive's red tile with white letters (02 section 6.3), drawn from mdi:file-pdf-box.
 * The body is our own constant, generated by scripts/extract-mdi.mjs.
 */
export function FileTypeIcon({ kind, size = 24 }: FileTypeIconProps) {
  const { body, width, height } = FILE_PDF_BOX;
  return (
    <svg
      className={`${styles.tile} ${styles[kind]}`}
      width={size}
      height={size}
      viewBox={`0 0 ${width} ${height}`}
      aria-hidden="true"
      focusable="false"
    >
      {/* the cut-out of the letters spans x 5.5-19.5, y 9-15 of the 24 box; the tile is 3-21 */}
      <rect className={styles.letters} x="5" y="8.5" width="15" height="7" />
      <g dangerouslySetInnerHTML={{ __html: body }} />
    </svg>
  );
}
